-- Isolated/staging only. All fixtures rollback, no remote provider call.
begin;
create temp table _results0020(name text,result text) on commit drop;
grant all on _results0020 to authenticated,service_role;
create function pg_temp.ok0020(name text,pass boolean) returns void language plpgsql as $$begin if pass is not true then raise exception 'FAIL: %',name;end if;insert into _results0020 values(name,'PASS');end$$;
create function pg_temp.raises0020(sql text) returns boolean language plpgsql as $$begin execute sql;return false;exception when others then return true;end$$;
do $$
declare staff uuid:=gen_random_uuid();other_user uuid:=gen_random_uuid();q uuid;q2 uuid;cid uuid;other_customer uuid;ct uuid;inv uuid;mid uuid;jid uuid;key uuid:=gen_random_uuid();r jsonb;r2 jsonb;j operation_jobs;old_token uuid;begin_ok boolean;doc uuid;addr uuid;legacy uuid;idx integer;d date:=(now() at time zone 'Europe/Istanbul')::date;
begin
 insert into auth.users(id,email) values(staff,'staff-0020@example.invalid'),(other_user,'nonstaff-0020@example.invalid');
 insert into staff_roles(user_id,role) values(staff,'operations');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',staff,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 insert into quotes(title,email,package,billing_period,term_months,price,valid_until) values('TEST_0020','fixture@example.invalid','Pro','yıllık',12,1200,d+1) returning id into q;
 perform public.mark_quote_sent(q,'e-posta');
 r:=public.accept_quote(q,jsonb_build_object('address','Fixture adres','city','Fixture il','district','Fixture ilçe'));
 cid:=(r->>'customer_id')::uuid;ct:=(r->>'contract_id')::uuid;inv:=(r->>'invoice_id')::uuid;jid:=(r->>'job_id')::uuid;
 perform pg_temp.ok0020('accept creates candidate, preparation contract, prepaid internal invoice',(select status='aday' from customers where id=cid) and (select status='hazırlık' from contracts where id=ct) and (select status='bekliyor' and due_date=issue_date from invoices where id=inv));
 insert into customers(title,email,status) values('TEST OTHER 0020','other-0020@example.invalid','aday') returning id into other_customer;
 perform pg_temp.ok0020('queued contract cannot move to another customer',pg_temp.raises0020(format('update contracts set customer_id=%L where id=%L',other_customer,ct)));
 perform pg_temp.ok0020('initial invoice cannot move to another customer',pg_temp.raises0020(format('update invoices set customer_id=%L where id=%L',other_customer,inv)));
 perform pg_temp.ok0020('new invoice cannot cross customer/contract ownership',pg_temp.raises0020(format('insert into invoices(customer_id,contract_id,amount) values(%L,%L,1)',other_customer,ct)));
 perform pg_temp.ok0020('accept queues exactly one package',(select count(*)=1 from operation_jobs where contract_id=ct and kind='contract_package'));
 r2:=public.accept_quote(q);perform pg_temp.ok0020('duplicate acceptance returns same IDs',r2->>'customer_id'=r->>'customer_id' and r2->>'contract_id'=r->>'contract_id' and (r2->>'replayed')::boolean);
 perform pg_temp.ok0020('duplicate acceptance produces no second fiscal/contract/outbox',(select count(*)=1 from contracts where customer_id=cid) and (select count(*)=1 from invoices where contract_id=ct) and (select count(*)=1 from operation_jobs where contract_id=ct));
 perform pg_temp.ok0020('accept audit exists',(select count(*)=1 from audit_log where table_name='quote_acceptances' and customer_id=cid));
 insert into quotes(title,package,price,valid_until) values('TEST_DRAFT','Pro',1200,d+1) returning id into q2;
 perform pg_temp.ok0020('draft cannot be accepted',pg_temp.raises0020(format('select accept_quote(%L)',q2)));
 perform pg_temp.ok0020('staff cannot forge sent job',pg_temp.raises0020(format('update operation_jobs set state=''sent'' where id=%L',jid)));
 perform pg_temp.ok0020('staff cannot call worker ownership RPC',pg_temp.raises0020(format('select operation_claim(%L)',jid)));
 r:=public.receive_mail(key,cid,'tebligat',jsonb_build_object('sender','Fixture kurum','tracking_no','TEST-TRACK'));
 mid:=(r->>'mail_id')::uuid;
 r2:=public.receive_mail(key,cid,'tebligat');
 perform pg_temp.ok0020('cargo duplicate key same mail',(r2->>'mail_id')::uuid=mid and (r2->>'replayed')::boolean);
 perform pg_temp.ok0020('queued cargo cannot move to another customer',pg_temp.raises0020(format('update mail_items set customer_id=%L where id=%L',other_customer,mid)));
 perform pg_temp.ok0020('cargo default today/geldi',(select received_date=d and status='geldi' and notified_at is null from mail_items where id=mid));
 perform pg_temp.ok0020('staff edit cannot forge notified status',pg_temp.raises0020(format('update mail_items set status=''bildirildi'',notify_channel=''e-posta'' where id=%L',mid)));
 perform pg_temp.ok0020('staff edit cannot forge notification time',pg_temp.raises0020(format('update mail_items set notified_at=now(),notify_channel=''e-posta'' where id=%L',mid)));
 perform pg_temp.ok0020('cargo one durable notice',(select count(*)=1 from operation_jobs where mail_id=mid));
 perform pg_temp.ok0020('invalid cargo type rejected',pg_temp.raises0020(format('select receive_mail(%L,%L,''other'')',gen_random_uuid(),cid)));
 perform pg_temp.ok0020('foreign customer photo rejected',pg_temp.raises0020(format('select receive_mail(%L,%L,''kargo'',''{"photo_url":"secure:mail/other/x.png"}'')',gen_random_uuid(),cid)));
 perform pg_temp.ok0020('cannot reuse cargo key for another type',pg_temp.raises0020(format('select receive_mail(%L,%L,''kargo'')',key,cid)));
 execute 'reset role';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other_user,'role','authenticated')::text,true);execute 'set local role authenticated';
 perform pg_temp.ok0020('nonstaff RLS hides customers/contracts/jobs',(select count(*)=0 from customers where id=cid) and (select count(*)=0 from contracts where id=ct) and (select count(*)=0 from operation_jobs where customer_id=cid));
 perform pg_temp.ok0020('nonstaff acceptance rejected',pg_temp.raises0020(format('select accept_quote(%L)',q)));
 perform pg_temp.ok0020('nonstaff cargo rejected',pg_temp.raises0020(format('select receive_mail(%L,%L)',gen_random_uuid(),cid)));
 perform pg_temp.ok0020('nonstaff retry rejected',pg_temp.raises0020(format('select retry_operation(%L)',jid)));
 execute 'reset role';
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 select * into j from operation_claim(jid);old_token:=j.claim_token;
 perform pg_temp.ok0020('worker claim has DB ownership',j.state='preparing' and j.claim_token is not null);
 perform pg_temp.ok0020('concurrent claim cannot get same job',not exists(select 1 from operation_claim(jid)));
 perform pg_temp.ok0020('wrong owner cannot prepare',pg_temp.raises0020(format('select operation_prepare(%L,%L,''{}'')',jid,gen_random_uuid())));
 perform operation_prepare(jid,j.claim_token,'{"to":"fixture@example.invalid","subject":"x","text":"x","attachments":[]}');
 perform pg_temp.ok0020('owner begins send once',operation_begin_send(jid,j.claim_token));
 perform pg_temp.ok0020('second begin cannot repeat external send',not operation_begin_send(jid,j.claim_token));
 update operation_jobs set sending_at=now()-interval '11 minutes' where id=jid;
 perform operation_claim(jid);
 perform pg_temp.ok0020('stale sending becomes uncertain; no auto claim',(select state='uncertain' from operation_jobs where id=jid));
 perform pg_temp.ok0020('stale owner cannot mark sent',pg_temp.raises0020(format('select operation_finish(%L,%L,''sent'',null,''[]'',''old-owner'')',jid,old_token)));
 execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',staff,'role','authenticated')::text,true);execute 'set local role authenticated';
 perform pg_temp.ok0020('uncertain send cannot be retried blindly',pg_temp.raises0020(format('select retry_operation(%L)',jid)));
 execute 'reset role';perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 perform pg_temp.ok0020('arbitrary service write cannot forge notice',pg_temp.raises0020(format('update mail_items set status=''bildirildi'',notify_channel=''e-posta'' where id=%L',mid)));
 select * into j from operation_claim((select id from operation_jobs where mail_id=mid));
 perform operation_finish(j.id,j.claim_token,'blocked','customer_email_required','[{"code":"email","label":"E-posta gerekli"}]');
 perform pg_temp.ok0020('missing email keeps actual cargo unnotified',(select status='geldi' and notified_at is null from mail_items where id=mid));
 execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',staff,'role','authenticated')::text,true);execute 'set local role authenticated';perform retry_operation(j.id);
 execute 'reset role';perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 select * into j from operation_claim(j.id);perform operation_prepare(j.id,j.claim_token,'{"to":"fixture@example.invalid"}');perform operation_begin_send(j.id,j.claim_token);perform operation_finish(j.id,j.claim_token,'sent',null,'[]','fixture-provider-id');
 perform pg_temp.ok0020('provider acceptance marks notice, never delivery',(select status='bildirildi' and notified_at is not null and delivered_at is null from mail_items where id=mid));
 perform pg_temp.ok0020('sent job never reclaimed',not exists(select 1 from operation_claim(j.id)));
 -- Recipient correction keeps PDF references; generation changes the provider idempotency key.
 insert into operation_jobs(dedupe_key,kind,customer_id,prepared,state,error_code) values('test-recipient:'||cid,'mail_arrived',cid,jsonb_build_object('to','old@example.invalid','attachments',jsonb_build_array(jsonb_build_object('path','customers/'||cid||'/same.pdf'))),'failed','provider_rejected') returning * into j;
 execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',staff,'role','authenticated')::text,true);execute 'set local role authenticated';
 update customers set email='new@example.invalid' where id=cid;
 perform retry_operation(j.id);
 perform pg_temp.ok0020('safe retry updates recipient/generation, keeps same PDF',(select prepared->>'to'='new@example.invalid' and generation=2 and prepared->'attachments'->0->>'path'='customers/'||cid||'/same.pdf' from operation_jobs where id=j.id));
 execute 'reset role';perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 select * into j from operation_claim(j.id);
 update customers set email='changed-again@example.invalid' where id=cid;
 begin_ok:=operation_begin_send(j.id,j.claim_token);
 perform pg_temp.ok0020('atomic begin blocks recipient changed after preparation',not begin_ok and (select state='blocked' and error_code='recipient_changed' from operation_jobs where id=j.id));
 insert into operation_jobs(dedupe_key,kind,customer_id,invoice_id) values('test-poll:'||cid,'einvoice_issue',cid,null) returning id into jid;
 select * into j from operation_claim(jid);perform operation_defer(j.id,j.claim_token,'einvoice_processing',300);
 perform pg_temp.ok0020('fiscal pending schedules future claim',(select state='queued' and next_attempt_at>now()+interval '4 minutes' and claim_token is null from operation_jobs where id=jid));
 perform pg_temp.ok0020('fiscal next check is not claimed early',not exists(select 1 from operation_claim(jid)));
 update operation_jobs set next_attempt_at=now()-interval '1 second' where id=jid;
 perform pg_temp.ok0020('fiscal future check can resume safely',exists(select 1 from operation_claim(jid)));
 execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',staff,'role','authenticated')::text,true);execute 'set local role authenticated';
 insert into storage.objects(bucket_id,name) values('secure-docs','customers/'||cid||'/signed.pdf');
 insert into documents(customer_id,type,name,file_url) values(cid,'sozlesme','TEST signed','secure:customers/'||cid||'/signed.pdf') returning id into doc;
 perform pg_temp.ok0020('activation blocked before prepaid evidence',pg_temp.raises0020(format('select activate_customer(%L,%L,%L)',cid,ct,doc)));
 perform mark_invoice_paid_manual(inv,d,'havale',1200,'TEST-PAYMENT-0020');
 perform mark_invoice_paid_manual(inv,d,'havale',1200,'TEST-PAYMENT-0020');
 perform pg_temp.ok0020('manual payment retry is idempotent',(select status='ödendi' and payment_verified_at is not null from invoices where id=inv));
 perform pg_temp.ok0020('different payment cannot overwrite first proof',pg_temp.raises0020(format('select mark_invoice_paid_manual(%L,%L,''havale'',1200,''OTHER'')',inv,d)));
 perform pg_temp.ok0020('payment creates one durable fiscal job',(select count(*)=1 from operation_jobs where invoice_id=inv and kind='einvoice_issue'));
 perform pg_temp.ok0020('activation blocked without address document',pg_temp.raises0020(format('select activate_customer(%L,%L,%L)',cid,ct,doc)));
 insert into storage.objects(bucket_id,name) values('secure-docs','customers/'||cid||'/address.pdf');
 insert into documents(customer_id,type,name,file_url) values(cid,'isyeri_kullanim','TEST address','secure:customers/'||cid||'/address.pdf') returning id into addr;
 perform activate_customer(cid,ct,doc);
 perform pg_temp.ok0020('activation requires signed stored document/payment/address',(select status='aktif' from customers where id=cid) and (select signed_document_id=doc and signed_verified_at is not null from contracts where id=ct));
 execute 'reset role';perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 for idx in 1..5 loop
  legacy:=public.parasut_import_invoice(cid,(900020000000000000::bigint+idx)::text,1200,d-30,d-30,'e-arşiv','TEST-LEGACY-'||idx,gen_random_uuid()::text,'TEST ONLY historical import');
  update invoices set einvoice_pdf='secure:customers/'||cid||'/legacy-test-'||idx||'.pdf' where id=legacy;
  perform public.parasut_mark_paid(legacy,d-30,'havale',1200,'TEST-LEGACY-PAY-'||idx);
  perform pg_temp.ok0020('historical Paraşüt import '||idx||' creates no fiscal or email job',not exists(select 1 from operation_jobs where invoice_id=legacy));
 end loop;
 update invoices set einvoice_status='kesildi',einvoice_pdf='secure:customers/'||cid||'/panel-current-test.pdf' where id=inv;
 perform pg_temp.ok0020('current panel invoice still creates one PDF email job',(select count(*)=1 from operation_jobs where invoice_id=inv and kind='einvoice_pdf'));
 update invoices set einvoice_pdf='secure:customers/'||cid||'/panel-current-test.pdf' where id=inv;
 perform pg_temp.ok0020('repeated current panel PDF does not duplicate email job',(select count(*)=1 from operation_jobs where invoice_id=inv and kind='einvoice_pdf'));
 insert into invoices(customer_id,amount,status,source,parasut_invoice_id,einvoice_status,issue_date) values(cid,1200,'bekliyor','panel','900020000000000099','kesildi',d-30) returning id into legacy;
 perform public.parasut_mark_paid(legacy,d-30,'havale',1200,'TEST-OLD-PANEL-RECONCILE');
 perform pg_temp.ok0020('Paraşüt reconciliation does not enqueue an old panel fiscal job',not exists(select 1 from operation_jobs where invoice_id=legacy));
 execute 'reset role';perform set_config('request.jwt.claims','{}',true);
end$$;
table _results0020;
select count(*) as passed from _results0020;
rollback;
